// 📊 COLLECTEUR - Préserve tout avec debug binary
const webhookData = $input.item.json.body;

if (!webhookData?.contenu) {
  throw new Error('Contenu manquant');
}

console.log('📊 COLLECTEUR:');
console.log('- Contenu:', webhookData.contenu.length, 'chars');
console.log('- Binary input keys:', Object.keys($input.item.binary || {}));

// Examiner la structure binary
Object.keys($input.item.binary || {}).forEach(key => {
  const binaryItem = $input.item.binary[key];
  console.log(`📎 Binary [${key}]:`, {
    exists: !!binaryItem,
    hasData: !!(binaryItem?.data),
    hasId: !!(binaryItem?.id),
    type: binaryItem?.mimeType
  });
});

return {
  json: {
    contenu_pour_openai: webhookData.contenu,
    contenu_original: webhookData.contenu,
    subtitle_original: webhookData.subtitle || ''
  },
  binary: $input.item.binary || {}
};

// 🔗 FUSION + RENOMMAGE BINARY
const openAIResult = $input.item;
const collectorData = $node["📊 Collecteur"];

console.log('🔗 FUSION BINARY FIX:');

// Parse OpenAI
let aiTitle = 'Titre par défaut';
let aiSubtitle = 'Sous-titre par défaut';
let aiBody = 'Corps par défaut';

const aiResponse = openAIResult.json?.message?.content;
if (aiResponse) {
  try {
    const cleanResponse = aiResponse.replace(/```json\n?|```\n?/g, '').trim();
    const analysis = JSON.parse(cleanResponse);

    aiTitle = analysis.title || aiTitle;
    aiSubtitle = analysis.subtitle || aiSubtitle;
    aiBody = analysis.body || aiBody;

    console.log('✅ IA PARSING SUCCESS:', aiTitle);
  } catch (e) {
    console.log('❌ IA PARSING FAILED:', e.message);
  }
}

// RENOMMAGE BINARY pour Flask
const collectorBinary = collectorData?.binary || {};
const flaskBinary = {};

console.log('📎 BINARY PROCESSING:');
console.log('- Collector binary keys:', Object.keys(collectorBinary));

// Renommer la première clé binary vers 'images'
const binaryKeys = Object.keys(collectorBinary);
if (binaryKeys.length > 0) {
  const firstKey = binaryKeys[0];
  const binaryData = collectorBinary[firstKey];

  console.log('📎 Renommage:', firstKey, '→ images');
  console.log('📎 Binary data valid:', !!(binaryData && (binaryData.data || binaryData.id)));

  flaskBinary.images = binaryData;
} else {
  console.log('⚠️ Aucune donnée binary trouvée');
}

return {
  json: {
    ai_title: aiTitle,
    ai_subtitle: aiSubtitle,
    ai_body: aiBody,

    debug: {
      ai_parsing_success: aiTitle !== 'Titre par défaut',
      binary_original_keys: Object.keys(collectorBinary),
      binary_renamed_keys: Object.keys(flaskBinary),
      binary_ready_for_flask: Object.keys(flaskBinary).length > 0
    }
  },
  binary: flaskBinary
};

const flaskResponse = $input.item.json;
const fusionData = $input.first();

if (flaskResponse?.success) {
  return {
    json: {
      status: 'success',
      message: '🎉 Document créé avec IA + images !',
      project_id: flaskResponse.project_id,
      download_url: `http://host.docker.internal:5003/api/download/${flaskResponse.project_id}`,

      ai_content: {
        title: fusionData?.json?.ai_title,
        subtitle: fusionData?.json?.ai_subtitle,
        body_preview: fusionData?.json?.ai_body?.substring(0, 100) + '...'
      },

      technical_details: {
        ai_parsing_success: fusionData?.json?.debug?.ai_parsing_success,
        binary_processed: fusionData?.json?.debug?.binary_ready_for_flask,
        binary_keys_original: fusionData?.json?.debug?.binary_original_keys,
        binary_keys_final: fusionData?.json?.debug?.binary_renamed_keys
      }
    }
  };
}

return {
  json: {
    status: 'error',
    error: flaskResponse?.error || 'Erreur Flask',
    debug: {
      flask_response: flaskResponse,
      fusion_debug: fusionData?.json?.debug
    }
  }
};
